        JISREM.CLEANUP_CASE_QUEUE
    SET
        status = 'VALIDATION_FAILED',
        message = v_validation_error
    WHERE
        cleanup_id = '64974499-a0c6-4083-a2ae-63383778a9e7'
        AND charge_id = 590819;
   
    RETURN;
END IF;

END IF;

