        WHERE
            cleanup_id = '64974499-a0c6-4083-a2ae-63383778a9e7'
            AND charge_id = '1228793';

   IF 0 = 0 THEN
        COMMIT;
    ELSE
        ROLLBACK;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        v_error_message := SUBSTR(SQLERRM, 1, 512);

        ROLLBACK;
        
        JISREM.LOG
        (
            p_cleanup_id => '64974499-a0c6-4083-a2ae-63383778a9e7',
            p_charge_id    => '1228793',
            p_step_name  => 'EXCEPTION',
            p_message    => v_error_message
        );
        
        UPDATE JISREM.CLEANUP_CASE_QUEUE
        SET 
            status = 'PROCESSING_FAILED',
            message = v_error_message
        WHERE cleanup_id = '64974499-a0c6-4083-a2ae-63383778a9e7'
        AND charge_id = '1228793';
        
END;
